mapper.select:
SELECT id, matter_code, matter_name, category_id, department, description, guide_content, conditions, materials, process_steps, deadline_days, status, sort_order, create_time, update_time FROM matter_info
(matter_name LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%'))
AND category_id = #{categoryId}
AND status = #{status}
AND status = 1
ORDER BY sort_order, id
